import { useState, useEffect } from 'react';
import { fetchJobs, Job } from '../api/jobServices';

export const useJobs = () => {
    const [jobs, setJobs] = useState<Job[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let mounted = true;

        setLoading(true);
        fetchJobs()
            .then((data) => {
                if (mounted) setJobs(data || []);
            })
            .catch((err) => {
                console.error('Failed to fetch jobs in useJobs:', err);
                if (mounted) setJobs([]);
            })
            .finally(() => {
                if (mounted) setLoading(false);
            });

        return () => {
            mounted = false;
        };
    }, []);

    return { jobs, loading };
};
